public final class MainActivity extends Activity {
    static final int BG=0xff07110b, PANEL=0xff10251a, GREEN=0xff89ffac, MUTED=0xffa0c4aa;
    static final String[] PROVIDERS={"ChatGPT","Kimi","Claude","Gemini","Grok","DeepSeek","Perplexity","Microsoft Copilot"};
    static final String[] URLS={"https://chatgpt.com/","https://www.kimi.com/","https://claude.ai/","https://gemini.google.com/","https://grok.com/","https://chat.deepseek.com/","https://www.perplexity.ai/","https://copilot.microsoft.com/"};
    static final int PICK=101,EXPORT=102,BACKUP=103,RESTORE=104;
    final ExecutorService executor=Executors.newSingleThreadExecutor();Vault vault;LinearLayout root,body;String page="Home";boolean busy;int providerIndex=0;String account="";boolean direct;List<Vault.Record> selected=new ArrayList<>();Vault exportVault;File temporary;int format;char[] password;List<Uri> sharedFiles=new ArrayList<>();String sharedText="";boolean sharedPending;
    interface Work<T>{T run()throws Exception;}interface Done<T>{void accept(T value);}
    @Override public void onCreate(Bundle state){super.onCreate(state);try{vault=new Vault(this);clearStaging();home();handleShare(getIntent());}catch(Exception e){layout("Vault error");body.addView(label("Cannot open encrypted vault. No data has been deleted. "+e.getMessage(),16));}}
    @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);if(busy||temporary!=null){message("An operation or temporary export is active. Finish it, then share again.");return;}handleShare(i);}
    void clearStaging(){File[] fs=getFilesDir().listFiles();if(fs!=null)for(File f:fs)if(f.getName().startsWith("direct-")||f.getName().startsWith("restore-"))Vault.erase(f);File[] rs=vault.dir.listFiles();if(rs!=null)for(File f:rs)if(f.getName().startsWith("pending-"))Vault.erase(f);}
    int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    GradientDrawable panel(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(8));d.setStroke(dp(1),0xff2d6342);return d;}
    TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(GREEN);t.setTypeface(Typeface.MONOSPACE);t.setPadding(dp(3),dp(5),dp(3),dp(5));return t;}
    TextView note(String s){TextView t=label(s,14);t.setTextColor(MUTED);return t;}
    Button button(String s,View.OnClickListener cb){Button b=new Button(this);b.setAllCaps(false);b.setText(s);b.setTextColor(GREEN);b.setTextSize(14);b.setMinHeight(dp(48));b.setBackground(panel(PANEL));b.setPadding(dp(8),dp(8),dp(8),dp(8));b.setOnClickListener(v->{if(!busy)cb.onClick(v);});return b;}
    void add(View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(5),0,dp(5));body.addView(v,p);}
    void action(String title,String desc,Runnable r){add(button(title,v->r.run()));add(note(desc));}
    EditText edit(String hint,String value,boolean multi){EditText e=new EditText(this);e.setHint(hint);e.setText(value);e.setTextColor(GREEN);e.setHintTextColor(MUTED);e.setTextSize(15);e.setPadding(dp(10),dp(10),dp(10),dp(10));e.setBackground(panel(PANEL));e.setInputType(android.text.InputType.TYPE_CLASS_TEXT|(multi?android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE:0));e.setMinLines(multi?5:1);e.setGravity(Gravity.TOP|Gravity.START);return e;}
    Spinner spinner(String[] items,int pos){Spinner s=new Spinner(this);ArrayAdapter<String> a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,items);a.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(a);s.setSelection(Math.max(0,Math.min(pos,items.length-1)));return s;}
    void layout(String name){page=name;root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft()+dp(12),i.getSystemWindowInsetTop()+dp(8),i.getSystemWindowInsetRight()+dp(12),i.getSystemWindowInsetBottom()+dp(8));return i;});setContentView(root);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);ImageView icon=new ImageView(this);icon.setImageResource(R.drawable.ic_robot);head.addView(icon,new LinearLayout.LayoutParams(dp(48),dp(48)));TextView title=label("CLANK-CON",23);head.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(head);root.addView(note("LOCAL ARCHIVE TERMINAL / "+name.toUpperCase(Locale.ROOT)));ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);String[] names={"Home","Source","Vault","Backup"};for(String n:names){Button b=button(n,v->{if(temporary!=null){new AlertDialog.Builder(this).setMessage("Discard temporary import and leave export?").setNegativeButton("Stay",null).setPositiveButton("Discard",(d,w)->{disposeTemporary();navigate(n);}).show();return;}navigate(n);});b.setTextSize(12);LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(0,-2,1);q.setMargins(dp(2),dp(3),dp(2),0);nav.addView(b,q);}root.addView(nav);root.requestApplyInsets();}
    void navigate(String n){switch(n){case "Home":home();break;case "Source":source();break;case "Vault":vaultPage();break;default:backupPage();}}
    void home(){layout("Home");add(label("ARCHIVE CONTROL",21));action("Connect provider","Open the official site in a dedicated browser or DuckDuckGo. External login stays external.",this::source);action("Import conversations","Paste or share conversation text, select files or import provider archives.",()->importPage(false));action("Search encrypted vault","Review original content, select conversations and export to seven formats.",this::vaultPage);action("Backup / restore","Password-encrypted portable vault backups.",this::backupPage);add(note("No background syncing or automatic full-history retrieval. Imports retain supplied originals. Provider access and completeness are not assumed."));}
    void source(){layout("Source");add(label("PROVIDER",16));Spinner p=spinner(PROVIDERS,providerIndex);add(p);EditText acct=edit("Local account label (not a password)",account,false);add(acct);add(label("BUILT-IN PROFILE",16));Spinner prof=spinner(new String[]{"A - persistent","B - persistent"},0);add(prof);add(button("Open built-in browser",v->{providerIndex=p.getSelectedItemPosition();account=acct.getText().toString();Intent i=new Intent(this,prof.getSelectedItemPosition()==0?ProbeActivity.BrowserA.class:ProbeActivity.BrowserB.class);i.putExtra("provider",providerIndex);startActivity(i);}));add(button("Open in DuckDuckGo",v->{providerIndex=p.getSelectedItemPosition();account=acct.getText().toString();openExternal(true);}));add(button("Open in default browser",v->{providerIndex=p.getSelectedItemPosition();account=acct.getText().toString();openExternal(false);}));add(note("The built-in browser uses its own persistent sessions. DuckDuckGo or another external browser keeps its own login. Returning here does not connect an account or grant access to its history. Use the provider's copy/share or download option, then import the actual conversation text/file. A shared URL alone is not conversation content."));add(button("Continue to import",v->{providerIndex=p.getSelectedItemPosition();account=acct.getText().toString();importPage(false);}));}
    void openExternal(boolean duck){Intent i=new Intent(Intent.ACTION_VIEW,Uri.parse(URLS[providerIndex]));i.addCategory(Intent.CATEGORY_BROWSABLE);if(duck)i.setPackage("com.duckduckgo.mobile.android");try{startActivity(i);}catch(ActivityNotFoundException e){message("Requested browser is not available");}}
    void handleShare(Intent i){if(i==null)return;String a=i.getAction();if(!Intent.ACTION_SEND.equals(a)&&!Intent.ACTION_SEND_MULTIPLE.equals(a)&&!Intent.ACTION_PROCESS_TEXT.equals(a))return;sharedFiles.clear();sharedText="";CharSequence t=i.getCharSequenceExtra(Intent.ACTION_PROCESS_TEXT.equals(a)?Intent.EXTRA_PROCESS_TEXT:Intent.EXTRA_TEXT);if(t!=null)sharedText=t.toString();if(Intent.ACTION_SEND_MULTIPLE.equals(a)){ArrayList<Uri> u=i.getParcelableArrayListExtra(Intent.EXTRA_STREAM);if(u!=null)for(Uri x:u)if(x!=null&&"content".equals(x.getScheme()))sharedFiles.add(x);}else{Uri u=i.getParcelableExtra(Intent.EXTRA_STREAM);if(u!=null&&"content".equals(u.getScheme()))sharedFiles.add(u);}if(sharedFiles.isEmpty()&&sharedText.isEmpty()){message("No supported shared content received");return;}sharedPending=true;importPage(true);}
    void importPage(boolean share){layout("Import");add(label("SOURCE DETAILS",16));Spinner p=spinner(PROVIDERS,providerIndex);add(p);EditText acct=edit("Local account label",account,false);add(acct);EditText title=edit("Conversation title","",false);add(title);Spinner mode=spinner(new String[]{"Save to encrypted vault","Export only (no retained vault record)"},0);add(mode);EditText text=edit("Paste conversation text here",share?sharedText:"",true);add(text);if(share&&!sharedFiles.isEmpty())add(note(sharedFiles.size()+" shared file(s) ready for import. Review provider and account before accepting."));add(note("A URL is only a reference. Share or copy the conversation content itself. Source files are preserved byte-for-byte; known ChatGPT JSON graphs can be expanded into separate records."));
        Runnable settings=()->{providerIndex=p.getSelectedItemPosition();account=acct.getText().toString().trim();direct=mode.getSelectedItemPosition()==1;};
        add(button("Save / export text",v->{settings.run();String s=text.getText().toString();if(s.trim().isEmpty()){message("Paste conversation content first");return;}if(s.trim().matches("https?://\\S+")){message("Only a URL was provided. Copy the actual conversation text or import a file.");return;}String name=title.getText().toString().trim();ingest(Collections.emptyList(),s,name.isEmpty()?"Shared conversation":name);}));
        if(share&&!sharedFiles.isEmpty())add(button("Accept shared file(s)",v->{settings.run();ingest(new ArrayList<>(sharedFiles),"","");}));
        add(button("Choose file(s)",v->{settings.run();Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,PICK);}));
        if(share)add(button("Discard shared content",v->{sharedPending=false;sharedText="";sharedFiles.clear();home();}));
    }
    String filename(Uri u){try(Cursor c=getContentResolver().query(u,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst()&&c.getString(0)!=null)return c.getString(0);}return "Imported file";}
    InputStream input(Uri u)throws IOException{InputStream in=getContentResolver().openInputStream(u);if(in==null)throw new IOException("Cannot open selected source");return in;}
    OutputStream output(Uri u)throws IOException{OutputStream o=getContentResolver().openOutputStream(u,"wt");if(o==null)throw new IOException("Cannot write destination");return o;}
    void ingest(List<Uri> uris,String text,String name){final String provider=PROVIDERS[providerIndex],acct=account;final boolean only=direct;run("Importing and authenticating originals",()->{Vault target=vault;File stage=null;if(only){stage=new File(getFilesDir(),"direct-"+UUID.randomUUID());target=new Vault(stage,vault.key);}ArrayList<String> warnings=new ArrayList<>();int saved=0;try{if(!text.isEmpty()){try(InputStream in=new ByteArrayInputStream(Vault.utf8(text))){target.add(provider,acct,name,"text/plain","User-supplied text",in);saved++;}}for(Uri u:uris){String n=filename(u);String m=getContentResolver().getType(u);if(m==null)m="application/octet-stream";try(InputStream in=input(u)){Vault.Record r=target.add(provider,acct,n,m,"User-selected original",in);saved++;try{target.expandChatGpt(r);}catch(Exception ex){warnings.add(n+": original preserved; graph expansion failed: "+ex.getMessage());}}catch(Exception ex){warnings.add(n+": not imported: "+ex.getMessage());}}if(saved==0)throw new IOException("Nothing imported. "+warnings);return new ImportResult(target,stage,saved,warnings);}catch(Exception e){if(stage!=null)Vault.erase(stage);throw e;}},r->{sharedFiles.clear();sharedText="";sharedPending=false;if(only){exportVault=r.target;temporary=r.stage;run("Reading temporary records",r.target::list,records->{selected=records;exportPage(true);if(!r.warnings.isEmpty())message(String.join("\n",r.warnings));});}else{vaultPage();message("Accepted "+r.saved+" source(s); duplicate originals are reused. "+(r.warnings.isEmpty()?"":String.join("\n",r.warnings)));}});}
    static final class ImportResult{final Vault target;final File stage;final int saved;final List<String>warnings;ImportResult(Vault t,File f,int s,List<String>w){target=t;stage=f;saved=s;warnings=w;}}
    void vaultPage(){layout("Vault");add(label("SEARCH ARCHIVE",17));EditText query=edit("Title, provider, account or content","",false);add(query);Spinner p=spinner(new String[]{"All providers","ChatGPT","Kimi","Claude","Gemini","Grok","DeepSeek","Perplexity","Microsoft Copilot"},0);add(p);add(button("Search",v->loadResults(query.getText().toString(),p.getSelectedItemPosition())));add(button("Show all",v->loadResults("",0)));add(note("Content search supports UTF-8 text/JSON up to 16 MiB per record. Larger originals and binary files remain intact but are metadata-searchable only."));}
    void loadResults(String query,int p){run("Reading encrypted vault",()->{List<Vault.Record> rs=vault.list(),out=new ArrayList<>();String q=query.toLowerCase(Locale.ROOT);int skipped=0;for(Vault.Record r:rs){if(p>0&&!r.provider().equals(PROVIDERS[p-1]))continue;if(q.isEmpty()||(r.title()+" "+r.provider()+" "+r.account()+" "+r.meta.optString("source")).toLowerCase(Locale.ROOT).contains(q)){out.add(r);continue;}if(Vault.isText(r)&&r.meta.optLong("size")<=Vault.TEXT_LIMIT){try{if(vault.rawText(r).toLowerCase(Locale.ROOT).contains(q))out.add(r);}catch(Exception e){skipped++;}}else skipped++;}return new SearchResult(out,skipped);},r->results(r));}
    static final class SearchResult{final List<Vault.Record> records;final int skipped;SearchResult(List<Vault.Record> r,int s){records=r;skipped=s;}}
    void results(SearchResult result){showResults(result,0,new LinkedHashSet<String>());}
    void showResults(SearchResult result,int offset,Set<String> ids){layout("Results");int end=Math.min(result.records.size(),offset+40);add(label(result.records.size()+" archive record(s) / "+ids.size()+" selected",18));if(result.skipped>0)add(note(result.skipped+" record(s) could not be content-searched; metadata was still checked."));add(button("Back to search",v->vaultPage()));add(button("Select all results",v->{for(Vault.Record r:result.records)ids.add(r.id());showResults(result,offset,ids);}));add(button("Clear selection",v->{ids.clear();showResults(result,offset,ids);}));add(button("Export selected",v->{selected=new ArrayList<>();for(Vault.Record r:result.records)if(ids.contains(r.id()))selected.add(r);if(selected.isEmpty()){message("Select at least one record");return;}exportVault=vault;exportPage(false);}));if(offset>0)add(button("Previous 40",v->showResults(result,Math.max(0,offset-40),ids)));if(end<result.records.size())add(button("Next 40",v->showResults(result,end,ids)));add(note(result.records.isEmpty()?"No records match. Import conversation content first.":"Showing "+(offset+1)+"–"+end));for(int j=offset;j<end;j++){Vault.Record r=result.records.get(j);LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(8),dp(6),dp(8),dp(6));panel.setBackground(panel(PANEL));CheckBox c=new CheckBox(this);c.setText(r.title());c.setTextColor(GREEN);c.setChecked(ids.contains(r.id()));c.setOnCheckedChangeListener((v,checked)->{if(checked)ids.add(r.id());else ids.remove(r.id());});panel.addView(c);panel.addView(note(r.provider()+" / "+r.account()+" / "+r.meta.optLong("size")+" bytes"));panel.addView(button("Review",v->review(r)));add(panel);}if(end<result.records.size())add(button("Next 40",v->showResults(result,end,ids)));}
    void review(Vault.Record r){layout("Review");add(label(r.title(),20));add(note(Exports.header(r)));add(button("Export this record",v->{selected=new ArrayList<>(Collections.singletonList(r));exportVault=vault;exportPage(false);}));if(r.provider().equals("ChatGPT")&&(vault.isZip(r)||r.kind().contains("json")||r.title().toLowerCase(Locale.ROOT).endsWith(".json")))add(button("Expand supplied ChatGPT conversation graphs",v->run("Expanding supplied graphs",()->vault.expandChatGpt(r),x->{message("Processed "+x+" graph(s). Original preserved; duplicates reused.");vaultPage();})));if(r.kind().contains("json")||r.title().toLowerCase(Locale.ROOT).endsWith(".json"))add(button("Explore supplied response branches",v->run("Reading graph",()->new Graph(vault.rawText(r)),g->branchPage(r,g))));if(vault.isZip(r))add(button("Expand archive files / attachments",v->new AlertDialog.Builder(this).setMessage("This retains each supplied ZIP entry as a separate encrypted record and can use substantial storage. The original archive is retained. Continue?").setNegativeButton("Cancel",null).setPositiveButton("Expand",(d,w)->run("Importing archive members",()->vault.expandFiles(r),n->{message("Processed "+n+" archive file(s). Original ZIP retained.");vaultPage();})).show()));add(button("Back to vault",v->vaultPage()));if(r.kind().startsWith("image/")){run("Reading image preview",()->{android.graphics.BitmapFactory.Options opts=new android.graphics.BitmapFactory.Options();opts.inJustDecodeBounds=true;try(InputStream in=vault.open(r)){android.graphics.BitmapFactory.decodeStream(in,null,opts);}int sample=1;while(Math.max(opts.outWidth,opts.outHeight)/sample>1200)sample*=2;opts.inJustDecodeBounds=false;opts.inSampleSize=sample;try(InputStream in=vault.open(r)){android.graphics.Bitmap b=android.graphics.BitmapFactory.decodeStream(in,null,opts);if(b==null)throw new IOException("Unsupported image encoding");return b;}},b->{ImageView image=new ImageView(this);image.setAdjustViewBounds(true);image.setImageBitmap(b);add(image);add(note("Preview only. JSON and ZIP retain exact original bytes."));});}else run("Reading original",()->vault.render(r),s->{LinearLayout part=new LinearLayout(this);part.setOrientation(LinearLayout.VERTICAL);add(part);showTextPart(part,s,0);});}
    void branchPage(Vault.Record r,Graph graph){layout("Branches");add(label(r.title(),18));String[] names=new String[graph.ends.size()];for(int j=0;j<names.length;j++){String id=graph.ends.get(j);names[j]=(id.equals(graph.current)?"Current: ":"Endpoint: ")+id;}Spinner branch=spinner(names,0);add(branch);add(note("Branches shown are endpoints in the supplied graph, not a claim that every server-side branch was retrieved."));LinearLayout preview=new LinearLayout(this);preview.setOrientation(LinearLayout.VERTICAL);add(button("Show branch",v->{String id=graph.ends.get(branch.getSelectedItemPosition());run("Reading branch path",()->graph.render(id),t->showTextPart(preview,t,0));}));add(button("Save selected branch as derived record",v->{String id=graph.ends.get(branch.getSelectedItemPosition());run("Saving branch",()->{byte[] raw=Vault.utf8(graph.branch(id).toString());try(InputStream in=new ByteArrayInputStream(raw)){return vault.add(r.provider(),r.account(),r.title()+" / branch "+id,"application/json","Derived from original graph "+r.id()+"; original retained",in);}},record->{message("Branch saved independently. The original graph is unchanged.");review(record);});}));add(button("Return to original",v->review(r)));add(preview);}
    void showTextPart(LinearLayout part,String text,int start){part.removeAllViews();int end=Math.min(text.length(),start+16000);if(end<text.length()&&end>start&&Character.isHighSurrogate(text.charAt(end-1)))end--;final int next=end;part.addView(note("Characters "+(start+1)+"–"+end+" of "+text.length()+". Export includes the complete renderable record."));if(start>0)part.addView(button("Previous segment",v->{int prev=Math.max(0,start-16000);if(prev>0&&Character.isLowSurrogate(text.charAt(prev)))prev--;showTextPart(part,text,prev);}));TextView t=label(text.substring(start,end),13);t.setTextIsSelectable(true);part.addView(t);if(next<text.length())part.addView(button("Next segment",v->showTextPart(part,text,next)));}
    void exportPage(boolean only){layout("Export");add(label(selected.size()+" selected record(s)",18));Spinner f=spinner(Exports.FORMATS,0);add(f);add(note("JSON and ZIP preserve exact source bytes. Text, Markdown, HTML, DOCX and PDF render supplied text/JSON; binary originals are represented by metadata. Text rendering limit: 16 MiB per original. Use ZIP for intact large originals or attachments. Exported files are not encrypted; use Backup for encrypted portability."));add(button("Choose destination",v->{format=f.getSelectedItemPosition();Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(Exports.MIME[format]);i.putExtra(Intent.EXTRA_TITLE,"Clank-Con-"+System.currentTimeMillis()+"."+Exports.EXT[format]);startActivityForResult(i,EXPORT);}));if(only)add(button("Cancel and discard temporary import",v->{disposeTemporary();home();}));}
    void disposeTemporary(){if(temporary!=null)Vault.erase(temporary);temporary=null;exportVault=null;selected.clear();}
    void backupPage(){layout("Backup");add(note("Portable backups use AES-256-GCM authenticated frames and PBKDF2-HMAC-SHA256 (600,000 iterations). Keep the passphrase; it cannot be recovered. Restore verifies the complete backup before adding records. Existing matching IDs are retained."));add(button("Create encrypted backup",v->passwordDialog(false)));add(button("Restore encrypted backup",v->passwordDialog(true)));}
    void passwordDialog(boolean restore){EditText pass=edit("Backup passphrase","",false);pass.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);pass.setTransformationMethod(PasswordTransformationMethod.getInstance());pass.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);new AlertDialog.Builder(this).setTitle(restore?"Restore passphrase":"Backup passphrase (12+ characters)").setView(pass).setNegativeButton("Cancel",(d,w)->pass.setText("")).setPositiveButton("Continue",(d,w)->{char[] chars=new char[pass.length()];pass.getText().getChars(0,pass.length(),chars,0);pass.setText("");if(chars.length<(restore?1:12)){Arrays.fill(chars,'\0');message("Passphrase is too short");return;}clearPassword();password=chars;Intent i=new Intent(restore?Intent.ACTION_OPEN_DOCUMENT:Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/octet-stream");if(!restore)i.putExtra(Intent.EXTRA_TITLE,"Clank-Con-"+System.currentTimeMillis()+".clankbak");startActivityForResult(i,restore?RESTORE:BACKUP);}).show();}
    void clearPassword(){if(password!=null)Arrays.fill(password,'\0');password=null;}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null){if(request==BACKUP||request==RESTORE)clearPassword();return;}Uri u=data.getData();if(request==PICK){ArrayList<Uri> us=new ArrayList<>();if(data.getClipData()!=null){for(int j=0;j<data.getClipData().getItemCount();j++)us.add(data.getClipData().getItemAt(j).getUri());}else if(u!=null)us.add(u);if(!us.isEmpty())ingest(us,"","");return;}if(u==null){clearPassword();message("No destination or source selected");return;}if(request==EXPORT){if(exportVault==null||selected.isEmpty()){message("Export selection expired; select records again");return;}Vault target=exportVault;List<Vault.Record> rs=new ArrayList<>(selected);int f=format;run("Writing "+Exports.FORMATS[f],()->{try(OutputStream o=output(u)){Exports.export(target,rs,f,o);}catch(Exception e){try{android.provider.DocumentsContract.deleteDocument(getContentResolver(),u);}catch(Exception ignored){}throw e;}return null;},x->{if(temporary!=null){disposeTemporary();home();}message("Export completed");});}else if(request==BACKUP||request==RESTORE){if(password==null){message("Passphrase expired; restart operation");return;}char[] pass=password;password=null;run(request==BACKUP?"Encrypting backup":"Authenticating backup",()->{try{if(request==BACKUP){try(OutputStream o=output(u)){Backup.save(vault,pass,o);}catch(Exception e){try{android.provider.DocumentsContract.deleteDocument(getContentResolver(),u);}catch(Exception ignored){}throw e;}return 0;}try(InputStream in=input(u)){return Backup.restore(vault,pass,in);}}finally{Arrays.fill(pass,'\0');}},n->message(request==BACKUP?"Encrypted backup saved":"Restored "+n+" new record(s)"));}}
    void message(String s){if(!isFinishing()&&!isDestroyed())new AlertDialog.Builder(this).setTitle("CLANK-CON").setMessage(s).setPositiveButton("OK",null).show();}
    <T>void run(String title,Work<T> work,Done<T> done){if(busy){message("Another operation is running");return;}busy=true;ProgressDialog dialog=new ProgressDialog(this);dialog.setMessage(title);dialog.setCancelable(false);dialog.show();executor.execute(()->{try{T value=work.run();runOnUiThread(()->{busy=false;if(!isDestroyed()){dialog.dismiss();done.accept(value);}});}catch(Exception e){runOnUiThread(()->{busy=false;if(!isDestroyed()){dialog.dismiss();message("Operation failed: "+(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage())+"\nCheck destination if a partial file remains.");}});}});}
    @Override public void onBackPressed(){if(busy)return;if(temporary!=null){new AlertDialog.Builder(this).setMessage("Discard temporary import?").setNegativeButton("Keep editing",null).setPositiveButton("Discard",(d,w)->{disposeTemporary();home();}).show();}else if(!page.equals("Home"))home();else super.onBackPressed();}
    @Override protected void onDestroy(){clearPassword();executor.shutdown();super.onDestroy();}
}
